import {createHash} from 'node:crypto';
const digest=v=>createHash('sha256').update(String(v)).digest('hex');
export const positions={'كابتن':'التدريب','سيلز':'السيلز','هاوس كيبنج':'الهاوس كيبنج','كواليتي':'الجودة','HR':'الموارد البشرية','أسسمنت — دكتور علاج طبيعي':'الأسسمنت والعلاج الطبيعي','Outdoor':'Outdoor','Move':'Move'};
export function text(v,max=1000){if(typeof v!=='string'||!v.trim()||v.trim().length>max)throw Error('INVALID_INPUT');return v.trim()}
export function email(v){const s=text(v,254).toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s))throw Error('INVALID_EMAIL');return s}
export function phone(v){const s=text(v,40).replace(/[٠-٩]/g,c=>c.charCodeAt(0)-1632).replace(/[\s()-]/g,'');if(!/^\+?\d{8,15}$/.test(s))throw Error('INVALID_PHONE');return s}
export function safeUser(u){if(!u)return null;const {password_hash,...safe}=u;safe.id=Number(safe.id);return safe}
export function cairoDay(t=Date.now()){return new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Cairo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(t))}
export function geoDistance(a,b){const r=n=>n*Math.PI/180,x=Math.sin(r(b.lat-a.lat)/2)**2+Math.cos(r(a.lat))*Math.cos(r(b.lat))*Math.sin(r(b.lng-a.lng)/2)**2;return 6371000*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x))}
export function verifyLocation(branch,c){if(!branch||branch.lat===null||branch.lng===null||!Number.isFinite(branch.lat)||!Number.isFinite(branch.lng))throw Error('BRANCH_LOCATION_MISSING');if(!c||!Number.isFinite(c.latitude)||!Number.isFinite(c.longitude)||Math.abs(c.latitude)>90||Math.abs(c.longitude)>180||!Number.isFinite(c.accuracy)||c.accuracy<0||c.accuracy>30)throw Error('LOW_GPS_ACCURACY');const distance=geoDistance(branch,{lat:c.latitude,lng:c.longitude});if(distance+c.accuracy>80)throw Error('OUTSIDE_80_METERS');return {distance:Math.round(distance),accuracy:Math.ceil(c.accuracy)}}
export function personalStaff(u){return {id:Number(u.id),cloudId:String(u.id),name:u.full_name,email:u.email,phone:u.phone,job:u.position||u.requested_position,position:u.position||u.requested_position,department:positions[u.position||u.requested_position],branch:u.branch||u.requested_branch,salary:0,time:'—',status:'غائب',approvalStatus:u.status}}
export function emptyWorkspace(){return {staff:[],requests:[],tasks:[],shifts:[],checked:false,permissions:{},logs:[],branches:[],punches:[],audit:[],adjustments:[],attendanceOpening:[],archived:[],branchPermissions:{},seenRequests:[],accounts:[],breaks:[],points:[],ruleVersions:[],rules:{kioskEnabled:false,enabled:false,breakMinutes:15,maxBreaks:2,graceMinutes:0,redPerOverrun:1,greenToCancel:1,autoGreen:false,version:0},payrollDrafts:{},payrollRuns:[],hourlyProfiles:{},joinRequests:[],dailyAssignments:[],coachSessions:[],salesLeads:[],assessmentBookings:[],shiftAssignments:[],faultReports:[],shiftSwapRequests:[],pointObjections:[],managerRequests:[],announcements:[],announcementAcks:[],availabilities:[],documents:[],chatMessages:[],openShifts:[],policy:null,assessors:[],assessorsSeeded:false}}
export const legacyBranchLocations={'فرع الرخاوي':{lat:29.964248,lng:32.5560476},'فرع الرخاوي — سيدات':{lat:29.964248,lng:32.5560476},'فرع فودافون':{lat:29.9631855,lng:32.5572978}};
const branchReconcileMap={'الفرع الرئيسي':'فرع فودافون','فرع الرخاوي':'فرع الرخاوي — سيدات'};
export function reconcileBranches(db){const map=n=>branchReconcileMap[n]||n;const mapped=(db.branches||[]).map(b=>({...b,name:map(b.name)})),merged=[];for(const b of mapped){const existing=merged.find(x=>x.name===b.name);if(!existing)merged.push(b);else{if(!Number.isFinite(existing.lat)&&Number.isFinite(b.lat)){existing.lat=b.lat;existing.lng=b.lng}}}db.branches=merged;const rekey=row=>{if(row&&typeof row.branch==='string')row.branch=map(row.branch)};for(const key of ['staff','shifts','shiftAssignments','dailyAssignments','coachSessions','salesLeads','assessmentBookings','faultReports','availabilities','documents','punches','breaks','openShifts','assessors'])for(const row of db[key]||[])rekey(row);for(const a of db.announcements||[])if(a.scope&&a.scope.branch)a.scope.branch=map(a.scope.branch);seedAssessors(db);linkAssessors(db);return db}

export function defaultPolicy(){return {version:4,updatedAt:'',updatedBy:'',sections:[
{title:'الحضور والانصراف',body:'التسجيل من موبايلك وانت داخل نطاق الفرع (GPS)، من غير أي طلب موافقة. سجّل حضورك أول ما توصل وانصرافك قبل ما تمشي. لو نسيت تسجيل الانصراف، ورديتك هتظهر في «مراجعة الساعات» وتقدر تراجع الإدارة لتوثيق ساعاتك بعد التحقق. تسجيلك لا يتوقف أبدًا لأي سبب، ولازم تكون موجود في مقر عملك طول ساعات ورديتك المعتمدة.'},
{title:'البريكات',body:'ليك بريكين مدفوعين في اليوم، كل بريك ١٥ دقيقة، ومدتهم جزء من ساعات عملك — لا يُخصموا من مرتبك ولا من حضورك. البريك بيكون جوه ساعات الحضور المسجلة، ولازم تنهيه قبل تسجيل الانصراف. الإدارة بتنظم مواعيد البريكات بحيث خدمة الأعضاء ما تتأثرش. تجاوز مدة البريك المسموح بيتسجل كنقطة حمرا حسب لائحة النقاط.'},
{title:'التأخير',body:'الالتزام ببداية الوردية مسؤوليتك. التأخير بيتسجل تلقائيًا في النظام بالدقيقة من وقت تسجيل الحضور، مع مراعاة أي سماح بتحدده الإدارة للوردية. مفيش أي خصم تلقائي من المرتب بسبب التأخير. التأخير المتكرر بيتراجع مع الإدارة وبياخد تدرج جدول المخالفات: تنبيه شفهي موثق، بعده إنذار كتابي، وبعدها جزاء مقترح بعد التحقيق. وعندك حق الاعتراض على أي تسجيل تأخير من صفحتك.'},
{title:'الورديات والتسليم والاستلام',body:'جداول الورديات بتتنشر قبل المعاد والكل يلتزم بالمعلن في النظام. سلّم ورديتك لزميلك المستلم تسليم واضح: حالة القاعة والمعدات وأي ملاحظات تشغيلية. ممنوع تسيب مقر العمل قبل ما المستلم يوصل أو من غير إذن الإدارة.'},
{title:'السلوك المهني',body:'الاحترام المتبادل بين الزمايل والإدارة أساس شغلنا. ممنوع أي سلوك يسيء لزميل أو عضو أو لسمعة المكان. أي خلاف متعلق بالشغل بيتحل عن طريق الإدارة المباشرة.'},
{title:'المظهر العام والزي',body:'التزم بالمظهر اللائق وبالزي المعتمد من المنشأة طول الوردية، مع مراعاة قواعد النظافة الشخصية خصوصًا للعاملين في الأقسام الرياضية.'},
{title:'استخدام الهاتف المحمول',body:'الموبايل أثناء الوردية لمتطلبات الشغل بس: تسجيل الحضور، متابعة العملاء، وتطبيقات العمل. تجنّب الاستخدام الشخصي الطويل وانت بتقدم خدمة للأعضاء.'},
{title:'خدمة الأعضاء',body:'الترحيب بالأعضاء والرد على استفساراتهم أولوية لكل فريق العمل. أي شكوى أو ملاحظة من عضو بتتسجل وبتترفع للإدارة فورًا. ممنوع على أي موظف تقديم وعود مالية أو تعاقدية خارج صلاحياته المعتمدة.'},
{title:'انضباط المتابعة البيعية (السيلز)',body:'كل تواصل مع عميل (مكالمة، رسالة، زيارة) بيتوثق كتعليق في ملفه بالنظام في حينه. كل عميل قيد المتابعة ليه موعد متابعة جاي واضح ومسؤول متابعة محدد، والمتابعات المستحقة بتظهر في لوحة السيلز أول بأول عشان ميتنساش أي عميل. حالة العميل (مهتم / متابعة / إغلاق) بتتحدث فور تغيرها، ومواعيد التقييم والأسسمنت بتتوثق في النظام. وعند الإغلاق بتتحدث الحالة مع تعليق ختامي بالنتيجة.'},
{title:'الإجازات وتبديل الورديات',body:'طلبات الإجازة بتتقدم من النظام قبل الموعد بوقت كافي وبتسري بعد اعتماد الإدارة. تبديل الورديات بين الموظفين بيكون بموافقة الإدارة وتوثيقه في النظام. الإجازات المعتمدة بتظهر في جدولك ومش بتتحسب غياب.'},
{title:'نظام النقاط والاعتراض',body:'النقطة الحمرا: ملاحظة تأديبية بتتسجل في النظام بالسبب والتاريخ عند مخالفة قواعد العمل، زي تجاوز مدة البريك المسموح أو أي مخالفة توثقها الإدارة. النقطة الخضرا: تقدير موثق للالتزام المتميز. أي نقطة لازم يكون ليها سبب مكتوب واضح وتاريخ. النقاط سجل للمراجعة الإدارية ومبيترتبش عليها أي خصومات مالية تلقائية. عندك حق الاعتراض على أي نقطة من صفحتك، والإدارة بتفصل في الاعتراض بعد المراجعة، والنقطة اللي بيتقبل الاعتراض عليها بتتلغي وبيتوثق إلغاؤها في النظام.'},
{title:'الثواب والتقدير',body:'النقطة الخضرا بتتسجل تقديرًا للالتزام المتميز: انتظام في المواعيد، إنجاز مهام قبل وقتها، أو مستوى خدمة الأعضاء بيشيدوا بيه. الأعلى التزامًا في مواعيد الوردية والأعلى في تحقيق مستهدف المبيعات بيتقدروا واسمهم بيتعلن قدام الفريق. النقاط الخضرا والتقديرات بتترجم لمكافآت مادية أو معنوية (زي أولوية اختيار الورديات أو شهادة تقدير أو مكافأة مالية) حسب ما تقرره الإدارة وتعلنه — والقيم والضوابط المالية للمكافآت مقترح يضعه صاحب المنشأة.'},
{title:'الجزاءات وقواعد التدرج',body:'الجزاءات بتتدرج: تنبيه شفهي موثق في النظام، ثم إنذار كتابي، ثم خصم من الأجر الأساسي في حدود جدول المخالفات والحدود القانونية، ثم إيقاف مؤقت عن العمل بأجر كامل لحين انتهاء التحقيق في الحالات اللي تستوجب، والمخالفات الجسيمة بتخضع لأحكام قانون العمل مباشرة. تكرار نفس نوع المخالفة خلال سنة بيشدد الجزاء. مفيش أي خصم بيتنفذ إلا بعد استيفاء إجراءات التحقيق واعتماد الإدارة، وممنوع الجمع بين جزاءين عن نفس المخالفة.'},
{title:'جدول المخالفات (قايمة الخصومات)',body:'التدرج المعتمد (وكل القيم المالية مقترحة تُعتمد من صاحب المنشأة قبل العمل بها):\n• التأخير عن بداية الوردية: تنبيه شفهي، ثم إنذار كتابي، ثم خصم مقترح نص يوم، وعند التكرار يوم كامل مع التحقيق.\n• الغياب من غير إذن أو عذر مقبول: اليوم لا يُحتسب أجرًا مع إنذار كتابي من أول مرة، وعند التكرار خصم مقترح يوم بعد التحقيق.\n• ترك مقر العمل قبل نهاية الوردية من غير إذن: إنذار كتابي، وعند التكرار خصم مقترح نص يوم.\n• عدم تسجيل الحضور أو الانصراف من النظام: تنبيه شفهي، ثم إنذار كتابي عند التكرار (وبيتم إثبات الدوام بالتحقق من الإدارة).\n• الاستخدام الشخصي الطويل للموبايل أثناء خدمة الأعضاء: تنبيه شفهي، ثم إنذار كتابي.\n• عدم توثيق متابعات العملاء في النظام (السيلز): تنبيه شفهي، ثم إنذار كتابي ونقطة حمرا.\n• الإخلال بقواعد السلوك المهني أو الإساءة لزميل أو عضو: إنذار كتابي فوري مع تحقيق، وعند التكرار إيقاف مؤقت بأجر كامل لحين انتهاء التحقيق.\n• المخالفات الجسيمة (كالاعتداء أو السرقة أو إفشاء بيانات الأعضاء): بتخضع لأحكام قانون العمل مباشرة وقد توصل للفصل وفق الإجراءات القانونية.\nالحدود القانونية (قانون العمل رقم ١٤ لسنة ٢٠٢٥): الخصم عن المخالفة الواحدة لا يتجاوز أجر ٥ أيام من الأجر الأساسي، وإجمالي المقتطع وفاءً للجزاءات لا يتجاوز أجر ٥ أيام في الشهر الواحد، ولا يُجمع بين جزاءين عن المخالفة الواحدة.'},
{title:'إجراءات التحقيق وضمانات الموظف',body:'مفيش أي جزاء بيتوقع إلا بعد إبلاغك كتابة بالمنسوب إليك وسماع أقوالك وتحقيق دفاعك وإثبات ده في محضر بيتحفظ في ملفك، والقرار الصادر بالجزاء بيكون مسببًا. التحقيق بيبدأ خلال ٧ أيام على الأكثر من تاريخ اكتشاف المخالفة. ولو الجزاء إنذار أو خصم لا يزيد عن أجر يوم واحد ممكن التحقيق يكون شفاهة مع إثبات مضمونه في القرار. وعندك حق الاعتراض على أي نقطة أو جزاء من النظام، والإدارة بتفصل في الاعتراض بعد المراجعة.'},
{title:'أحكام عامة',body:'اللائحة دي سارية على كل العاملين بالمنشأة بكل الأقسام والفروع. يحق للإدارة تعديلها، وبيتم إخطاركم بأي تعديل من النظام مع تاريخ سريانه. واللي مفيهوش نص في اللائحة دي بيخضع لتقدير الإدارة بما يحقق مصلحة العمل وفي حدود قانون العمل المصري.'}]}}
const normName=v=>String(v||'').trim().replace(/[\u0623\u0625\u0622]/g,'\u0627').replace(/\u0649/g,'\u064a').replace(/\s+/g,' ');
export function defaultAssessors(){return [
 {id:'asr-yassin',name:'دكتور محمد ياسين',branch:'فرع فودافون',active:true,availability:{}},
 {id:'asr-hesham',name:'دكتور محمد هشام',branch:'فرع فودافون',active:true,availability:{}},
 {id:'asr-laila',name:'دكتورة ليلى',branch:'فرع الرخاوي — سيدات',active:true,availability:{}},
 {id:'asr-hana',name:'دكتورة هنا',branch:'فرع الرخاوي — سيدات',active:true,availability:{}}]}
const slotRange=(a,b)=>{const out=[];for(let m=a;m<b;m+=30)out.push(String(Math.floor(m/60)).padStart(2,'0')+':'+(m%60?'30':'00'));return out};
const confirmedSchedules={'asr-yassin':{days:[0,2,4,5],from:21*60,to:22*60+30},'asr-hesham':{days:[6,1,3],from:19*60+30,to:23*60},'asr-laila':{days:[6,1,3],from:17*60,to:21*60},'asr-hana':{days:[0,2,4],from:12*60,to:16*60}};
export function applyConfirmedAssessorSchedules(db){if(db.assessorScheduleV1)return db;for(const a of db.assessors||[]){const c=confirmedSchedules[a.id];if(!c||availabilityConfigured(a))continue;const slots=slotRange(c.from,c.to);a.availability={};for(const d of c.days)a.availability[String(d)]=[...slots]}db.assessorScheduleV1=true;return db}
export function seedAssessors(db){if(db.assessorsSeeded)return applyConfirmedAssessorSchedules(db);db.assessors=Array.isArray(db.assessors)?db.assessors:[];for(const a of defaultAssessors())if(!db.assessors.some(x=>normName(x.name)===normName(a.name)&&x.branch===a.branch))db.assessors.push({...a});db.assessorsSeeded=true;return applyConfirmedAssessorSchedules(db)}
export function linkAssessors(db){for(const a of db.assessors||[]){if(a.staffId)continue;const s=(db.staff||[]).find(s=>s.branch===a.branch&&s.position==='أسسمنت — دكتور علاج طبيعي'&&normName(s.name)===normName(a.name));if(s)a.staffId=Number(s.id)}return db}
export function validSlotTime(t){return /^([01]\d|2[0-3]):(00|30)$/.test(t)}
export function availabilityConfigured(a){return !!a&&Object.values(a.availability||{}).some(v=>Array.isArray(v)&&v.length)}
export function slotAllowed(a,day,time){if(!availabilityConfigured(a))return true;const wd=new Date(day+'T12:00:00Z').getUTCDay();return ((a.availability||{})[String(wd)]||[]).includes(time)}
function sameDoctor(row,ref){if(ref.assessorId&&String(row.assessorId||'')===String(ref.assessorId))return true;if(ref.staffId!=null&&Number(row.doctorId)===Number(ref.staffId))return true;if(!ref.assessorId&&ref.doctorId!=null&&Number(row.doctorId)===Number(ref.doctorId))return true;return false}
function slotTaken(db,branch,ref,day,time,ignoreId){return (db.assessmentBookings||[]).some(a=>String(a.id)!==String(ignoreId||'')&&a.branch===branch&&a.day===day&&a.time===time&&!['cancelled','postponed'].includes(a.bookingStatus)&&sameDoctor(a,ref))}
export function linkLegacyStaff(db,sourceId,targetId){
 const source=db.staff.find(s=>Number(s.id)===Number(sourceId)),target=db.staff.find(s=>Number(s.id)===Number(targetId));
 if(!source?.legacyProfileId||!source.needsActivation||!target?.cloudId||source.id===target.id)throw Error('INVALID_INPUT');
 if(db.staff.some(s=>s.legacyProfileId===source.legacyProfileId&&s.id!==source.id))throw Error('CONFLICT');
 const id=Number(target.id),merged={...source,...target,legacyProfileId:source.legacyProfileId,legacyEmail:source.legacyEmail||source.email,employeeCode:source.employeeCode,needsActivation:false,needsReview:false,legacyActive:source.legacyActive};
 for(const key of ['dailyAssignments','coachSessions','salesLeads','punches','breaks','points','requests','shiftAssignments','adjustments','attendanceOpening'])for(const row of db[key]||[])if(Number(row.employeeId)===Number(source.id)){row.employeeId=id;if('employeeName'in row)row.employeeName=target.name;if(key==='dailyAssignments'){row.branch=target.branch;row.department=target.department;}}
 // Do not rewrite closed payroll runs or historical timestamps/amounts.
 db.staff=db.staff.filter(s=>Number(s.id)!==Number(source.id)&&Number(s.id)!==id);db.staff.push(merged);
 return db;
}
export function materializeLegacyTasks(db,day=cairoDay()){
 const validDay=/^\d{4}-\d{2}-\d{2}$/.test(day);if(!validDay)return db;
 const weekday=d=>new Date(d+'T12:00:00Z').getUTCDay(),added=[];
 for(const t of db.dailyAssignments||[]){if(!t.legacyTaskId||t.id!=='legacy-task:'+t.legacyTaskId||t.legacyStatus!=='todo')continue;
  const person=db.staff.find(s=>Number(s.id)===Number(t.employeeId));if(!person||person.legacyActive===false)continue;
  const anchor=t.legacyDueDate;if(!anchor||anchor>day||anchor===day)continue;
  const due=t.legacyFrequency==='daily'||(t.legacyFrequency==='weekly'&&weekday(anchor)===weekday(day))||(t.legacyFrequency==='monthly'&&anchor.slice(8)===day.slice(8));
  const id='legacy-repeat:'+t.legacyTaskId+':'+day;if(due&&!db.dailyAssignments.some(x=>x.id===id))added.push({...t,id,day,status:'assigned',completionNote:'',completedAt:null,reviewedAt:null,returnReason:''});
 }
 db.dailyAssignments.push(...added);return db;
}
