export function kioskPunch(db,staff,direction,now=Date.now()){
 const at=new Date(now).toISOString(),id=Number(staff.id),uid=()=>now+Math.floor(Math.random()*100000);
 const open=db.punches.find(p=>p.employeeId===id&&!p.out);
 if(direction==='in'){
  if(open||db.punches.some(p=>p.employeeId===id&&cairoDay(p.in)===cairoDay(now)))throw Error('ALREADY_CHECKED_IN');
  db.punches.push({id:uid(),employeeId:id,name:staff.name,branch:staff.branch,in:at,out:null,inLocation:{kiosk:true},source:'kiosk'});
 }else if(direction==='out'){
  if(!open)throw Error('NO_OPEN_SHIFT');
  if(db.breaks.some(b=>b.employeeId===id&&!b.end))throw Error('BREAK_OPEN');
  open.out=at;open.outLocation={kiosk:true};open.source=open.source||'kiosk';
 }else throw Error('INVALID_INPUT');
 db.audit.push({at,actor:'كشك '+staff.branch,action:'kiosk_'+direction,subject:staff.name});
 return db;
}
export function findStaffByPin(db,branch,pin){const h=digest(pin);return (db.staff||[]).find(s=>s.branch===branch&&s.pinHash===h)||null}
export function pinDigest(pin){return digest(pin)}
